    ["|cffffff00Scavenger went quiet during looting. Resummoning when you stop moving.|r"] = "|cffffff00Scavenger wurde beim Plündern still. Wird erneut beschworen, sobald du stehen bleibst.|r",
    ["|cffff4444Auto-deleted|r %s."] = "|cffff4444Automatisch gelöscht|r %s.",
    ["|cffff4444Marked for deletion (Resilience, unsellable):|r %s"] = "|cffff4444Zum Löschen markiert (Abhärtung, nicht verkäuflich):|r %s",
    ["|cffff4444Marked for delete|r %s - affix you can't sell (no vendor value)."] = "|cffff4444Zum Löschen markiert|r %s - Affix, den du nicht verkaufen kannst (kein Händlerwert).",
    -- v2.50.2: recovery hint suffix appended to both auto-mark chat messages.
    ["|cffaaaaaaAdd to Keep List (Alt+Right-Click on the bag slot) to save it.|r"] = "|cffaaaaaaZur Behalten-Liste hinzufügen (Alt+Rechtsklick auf den Taschenplatz), um ihn zu sichern.|r",
    ["|cffffff00Sold %d items this trip (%d more left). Talk to the merchant again to sell the rest.|r"] = "|cffffff00%d Gegenstände bei diesem Besuch verkauft (%d übrig). Sprich den Händler erneut an, um den Rest zu verkaufen.|r",
    ["Sold |cffffff00%d|r items so far. Checking for more..."] = "Bisher |cffffff00%d|r Gegenstände verkauft. Suche nach weiteren...",
    ["Vendoring complete! Sold |cffffff00%d|r items. |cffb6ffb6Money Collected:|r %s"] = "Verkauf abgeschlossen! |cffffff00%d|r Gegenstände verkauft. |cffb6ffb6Erhaltenes Gold:|r %s",
    ["Repaired from guild bank: %s"] = "Aus der Gildenbank repariert: %s",
    ["Nothing to sell."] = "Nichts zu verkaufen.",
    ["Reset |cffb6ffb6EbonClearance|r lifetime stats?\n|cffaaaaaaThis clears money earned, items sold, items deleted, and repair totals. Session stats are not affected.|r"] = "|cffb6ffb6EbonClearance|r Gesamtwerte zurücksetzen?\n|cffaaaaaaDas löscht verdientes Gold, verkaufte Gegenstände, gelöschte Gegenstände und Reparaturkosten. Sitzungswerte bleiben erhalten.|r",
    ["Reset session stats?"] = "Sitzungswerte zurücksetzen?",
    ['Delete profile "|cffffff00%s|r"?\n|cffaaaaaaThis cannot be undone.|r'] = 'Profil "|cffffff00%s|r" löschen?\n|cffaaaaaaDas kann nicht rückgängig gemacht werden.|r',
    ['Clear all items from profile "|cffffff00%s|r"?\n|cffaaaaaaThe profile itself will remain.|r'] = 'Alle Gegenstände aus Profil "|cffffff00%s|r" entfernen?\n|cffaaaaaaDas Profil selbst bleibt erhalten.|r',
    ['Remove every item from "|cffffff00%s|r"?\n|cffaaaaaaThis cannot be undone.|r'] = 'Jeden Gegenstand aus "|cffffff00%s|r" entfernen?\n|cffaaaaaaDas kann nicht rückgängig gemacht werden.|r',
    ["Auto-delete permanently destroys Delete List items the instant they're looted - no vendor step, no undo. Turn it on?"] = "Auto-Löschen zerstört Gegenstände der Löschliste dauerhaft, sobald sie geplündert werden - kein Händlerschritt, kein Rückgängig. Einschalten?",
    ["Remove |cffffff00%d|r stale 'Upgrade'-tagged entries from your Keep List?\n|cffaaaaaaThese items were auto-tagged as upgrades but are no longer above your currently-equipped iLvl. Manual Keep List entries (no auto-tag) and 'Worn'-tagged entries are not affected.|r"] = "|cffffff00%d|r veraltete, als 'Verbesserung' markierte Einträge aus deiner Behalten-Liste entfernen?\n|cffaaaaaaDiese Gegenstände wurden automatisch als Verbesserung markiert, liegen aber nicht mehr über deiner aktuell angelegten Gegenstandsstufe. Manuelle Behalten-Einträge (ohne Auto-Markierung) und als 'Getragen' markierte Einträge sind nicht betroffen.|r",
    ["Apply %s?\n\nThis changes your speed, protection, auto-sell, and visual settings.\n\nYour |cffb6ffb6Sell|r, |cffb6ffb6Keep|r, and |cffb6ffb6Delete|r lists stay exactly as they are."] = "%s anwenden?\n\nDas ändert deine Einstellungen für Tempo, Schutz, Auto-Verkauf und Optik.\n\nDeine Listen |cffb6ffb6Verkaufen|r, |cffb6ffb6Behalten|r und |cffb6ffb6Löschen|r bleiben genau so, wie sie sind.",
    ["|cff00ff00No list conflicts found.|r"] = "|cff00ff00Keine Listenkonflikte gefunden.|r",
    ["Found |cffffff00%d|r item(s) present in multiple lists:"] = "|cffffff00%d|r Gegenstand/Gegenstände in mehreren Listen gefunden:",
