    ["Known affixes: %d descriptions / %d families. Project Ebonhold affix data: %s."] = "Bekannte Affixe: %d Beschreibungen / %d Familien. Project Ebonhold Affix-Daten: %s.",
    ["Matched your %s auto-sell rule (it sells all items of that rarity)%s."] = "Passt zu deiner %s Auto-Verkaufsregel (sie verkauft alle Gegenstände dieser Seltenheit)%s.",
