    -- v2.49.0 chance-on-hit auto-release (experimental)
    ["Sell known chance-on-hit procs (experimental)"] = "Bekannte 'Chance bei Treffer' verkaufen (experimentell)",
    ["Keep (chance-on-hit proc known)"] = "Behalten (Chance bei Treffer bekannt)",
    ["Will Sell (chance-on-hit proc known)"] = "Wird verkauft (Chance bei Treffer bekannt)",
    ["chance-on-hit proc known (%s), 'Sell known chance-on-hit procs' is on"] = "Chance bei Treffer bekannt (%s), 'Bekannte Chance bei Treffer verkaufen' ist an",
    ["Off by default. When on, chance-on-hit weapons whose proc you've already extracted at the Anvil fall through the chance-on-hit protection - the auto-rule sweep can vendor them. Mirrors the affix side's 'Allow selling affixes you already have' toggle. Marked experimental because coverage relies on a hand-curated map of proc-text keywords to PE spell IDs; items whose proc PE hasn't ported to its 700xxx affix family stay protected regardless. If a specific item auto-sells when you didn't want it to, Alt+Right-Click and Keep-List it to override."] = "Standardmäßig aus. Wenn an, fallen Waffen mit Chance bei Treffer, deren Proc du am Amboss bereits extrahiert hast, durch den Chance-bei-Treffer-Schutz - die automatischen Regeln können sie verkaufen. Entspricht der Affix-Option 'Verkauf von Affixen erlauben, die du bereits hast'. Als experimentell gekennzeichnet, weil die Abdeckung auf einer handgepflegten Zuordnung von Proc-Textbegriffen zu PE-Zauber-IDs beruht; Gegenstände, deren Proc PE nicht in seine 700xxx-Affix-Familie übertragen hat, bleiben trotzdem geschützt. Wenn ein bestimmter Gegenstand automatisch verkauft wird, obwohl du das nicht wolltest, setze ihn per Alt+Rechtsklick auf die Behalten-Liste.",
    ["You've extracted this item's chance-on-hit proc at the Anvil. The item is still being kept because 'Sell known chance-on-hit procs (experimental)' is off. Turn that toggle on in Keep Settings if you want extras auto-sold."] = "Du hast den Chance-bei-Treffer-Proc dieses Gegenstands am Amboss extrahiert. Der Gegenstand wird trotzdem behalten, weil 'Bekannte Chance bei Treffer verkaufen (experimentell)' aus ist. Schalte diese Option in den Behalten-Einstellungen an, wenn zusätzliche Exemplare automatisch verkauft werden sollen.",
    ["Chance-on-hit item whose proc you've already extracted at the Anvil, and 'Sell known chance-on-hit procs (experimental)' is on. The auto-rule sweep will vendor it at the next merchant visit."] = "Gegenstand mit Chance bei Treffer, dessen Proc du am Amboss bereits extrahiert hast, und 'Bekannte Chance bei Treffer verkaufen (experimentell)' ist an. Die automatischen Regeln verkaufen ihn beim nächsten Händlerbesuch.",
    ["|cffff4444WILL DELETE at the next vendor visit|r"] = "|cffff4444WIRD beim nächsten Händlerbesuch GELÖSCHT|r",
    ["|cff00ff00WILL SELL at the next vendor visit|r"] = "|cff00ff00WIRD beim nächsten Händlerbesuch VERKAUFT|r",
    ["|cffffb84dwon't sell - no rule matched|r"] = "|cffffb84dwird nicht verkauft - keine Regel greift|r",
    ["|cffff4444won't sell - protected|r"] = "|cffff4444wird nicht verkauft - geschützt|r",
    ["internal: this explanation disagrees with the engine's verdict - the verdict above is what will happen. Please report this item via /ec bugreport."] = "Intern: Diese Erklärung widerspricht dem Urteil der Engine - das obige Urteil ist, was passieren wird. Bitte melde dieses Item per /ec bugreport.",
    ["(EC label check failed - please report via /ec bugreport)"] = "(EC-Beschriftungsprüfung fehlgeschlagen - bitte per /ec bugreport melden)",
    ["on Delete List but also on your Keep List - Keep List wins, not deleted"] = "auf der Löschliste, aber auch auf deiner Behalten-Liste - Behalten gewinnt, nicht gelöscht",
    ["on Delete List but on your Account Sell List - kept to sell, not deleted"] = "auf der Löschliste, aber auf deiner Account-Verkaufsliste - zum Verkauf behalten, nicht gelöscht",
    ["on Delete List but currently worn - not deleted"] = "auf der Löschliste, aber derzeit angelegt - nicht gelöscht",
    ["on Delete List but its affix is protected - not deleted"] = "auf der Löschliste, aber sein Affix ist geschützt - nicht gelöscht",
    ["on Delete List but the slot is locked (mid-pickup) - skipped this tick"] = "auf der Löschliste, aber der Platz ist gesperrt (wird gerade bewegt) - diesen Durchlauf übersprungen",

    -- v2.72.0 Settings Profiles + List Profiles rename
    ["List Profiles"] = "Listenprofile",
    ["What are List Profiles? (and how are they different from Quickstart?)"] = "Was sind Listenprofile? (und wie unterscheiden sie sich vom Schnellstart?)",
    ["List profiles save and restore your |cffb6ffb6Sell List|r and |cffb6ffb6Keep List|r as a named pair. Switching profiles overwrites the live character lists with the saved snapshot. Handy for swapping between farming spots. For your selling behaviour (rules, protections, speed), see |cffb6ffb6Settings Profiles|r."] = "Listenprofile speichern deine |cffb6ffb6Verkaufsliste|r und |cffb6ffb6Behalten-Liste|r als benanntes Paar und stellen sie wieder her. Ein Profilwechsel überschreibt die aktuellen Listen des Charakters mit dem gespeicherten Stand. Praktisch zum Wechseln zwischen Farmgebieten. Für das Verkaufsverhalten (Regeln, Schutz, Tempo) siehe |cffb6ffb6Einstellungsprofile|r.",
    ["List profiles are named snapshots of your |cffb6ffb6Sell List|r and |cffb6ffb6Keep List|r. Save your current lists as a profile, then later swap to a different one in a single click. Quickstart presets are different: they configure the addon's |cffffd870behaviour|r (speed, auto-sell rules, protections) but never touch your lists. For per-character behaviour, see Settings Profiles. Slash commands: /ec profile save <name>, /ec profile load <name>, /ec profile list, /ec profile delete <name>."] = "Listenprofile sind benannte Momentaufnahmen deiner |cffb6ffb6Verkaufsliste|r und |cffb6ffb6Behalten-Liste|r. Speichere deine aktuellen Listen als Profil und wechsle später mit einem Klick. Schnellstart-Voreinstellungen sind etwas anderes: Sie konfigurieren das |cffffd870Verhalten|r des Addons (Tempo, Verkaufsregeln, Schutz), rühren deine Listen aber nie an. Für Verhalten pro Charakter siehe Einstellungsprofile. Befehle: /ec profile save <Name>, /ec profile load <Name>, /ec profile list, /ec profile delete <Name>.",
    ["Show your saved List Profiles"] = "Deine gespeicherten Listenprofile anzeigen",
    ["Manage List Profiles by name |cffaaaaaa(or use the List Profiles panel)|r"] = "Listenprofile per Name verwalten |cffaaaaaa(oder über das Panel Listenprofile)|r",
    ["Show your Settings Profiles"] = "Deine Einstellungsprofile anzeigen",
    ["Manage Settings Profiles by name |cffaaaaaa(or use the Settings Profiles panel)|r"] = "Einstellungsprofile per Name verwalten |cffaaaaaa(oder über das Panel Einstellungsprofile)|r",
    ["Settings Profiles"] = "Einstellungsprofile",
    ["Settings Profiles:"] = "Einstellungsprofile:",
    ["What are Settings Profiles?"] = "Was sind Einstellungsprofile?",
    ["A settings profile holds a character's selling behaviour: merchant mode, rarity rules, protections, affix and recipe settings, deletion toggles, and vendor speed. Each character picks one on the Settings Profiles panel. Characters on the same profile share it live - change a setting on one and every character using that profile follows. To give one character its own settings, save a new profile there and press Use. Item lists, stats, looting, and visual options are not part of a settings profile. Slash command: /ec sprofile."] = "Ein Einstellungsprofil enthält das Verkaufsverhalten eines Charakters: Händlermodus, Seltenheitsregeln, Schutzoptionen, Affix- und Rezepteinstellungen, Löschoptionen und Verkaufstempo. Jeder Charakter wählt eines im Panel Einstellungsprofile. Charaktere mit demselben Profil teilen es live - ändere eine Einstellung auf einem und alle Charaktere mit diesem Profil folgen. Um einem Charakter eigene Einstellungen zu geben, speichere dort ein neues Profil und klicke auf Verwenden. Gegenstandslisten, Statistiken, Plündern und visuelle Optionen gehören nicht dazu. Befehl: /ec sprofile.",
    ["A settings profile holds this character's |cffb6ffb6selling behaviour|r: merchant mode, rarity rules, protections, affix and recipe settings, deletion toggles, and vendor speed. Each character picks one profile. Characters on the same profile share it live - change a setting on one and every character using that profile follows."] = "Ein Einstellungsprofil enthält das |cffb6ffb6Verkaufsverhalten|r dieses Charakters: Händlermodus, Seltenheitsregeln, Schutzoptionen, Affix- und Rezepteinstellungen, Löschoptionen und Verkaufstempo. Jeder Charakter wählt ein Profil. Charaktere mit demselben Profil teilen es live - ändere eine Einstellung auf einem und alle Charaktere mit diesem Profil folgen.",
    ["|cffaaaaaaItem lists, stats, looting, and visual options are not part of a settings profile. To give one character its own settings, save a new profile here and press Use on it.|r"] = "|cffaaaaaaGegenstandslisten, Statistiken, Plündern und visuelle Optionen gehören nicht zu einem Einstellungsprofil. Um einem Charakter eigene Einstellungen zu geben, speichere hier ein neues Profil und klicke auf Verwenden.|r",
    ["This character uses: "] = "Dieser Charakter verwendet: ",
    ["Save current settings as:"] = "Aktuelle Einstellungen speichern als:",
    ["Saved Settings Profiles"] = "Gespeicherte Einstellungsprofile",
    ["Use"] = "Verwenden",
    ["Rename this character's profile:"] = "Profil dieses Charakters umbenennen:",
    ["|cff00ff00%s|r  |cff888888(this character)|r"] = "|cff00ff00%s|r  |cff888888(dieser Charakter)|r",
    ["|cff00ff00%s|r  |cff888888(this character + %d more)|r"] = "|cff00ff00%s|r  |cff888888(dieser Charakter + %d weitere)|r",
    ["|cffffff00%s|r  |cff888888(%d character(s))|r"] = "|cffffff00%s|r  |cff888888(%d Charakter(e))|r",
    ["  |cffffff00%s|r - used by %d character(s)%s"] = "  |cffffff00%s|r - verwendet von %d Charakter(en)%s",
    [" |cff00ff00(this character)|r"] = " |cff00ff00(dieser Charakter)|r",
    ["Settings profiles are not ready yet."] = "Einstellungsprofile sind noch nicht bereit.",
    ['Saved settings as "|cffffff00%s|r" - this character now uses it.'] = 'Einstellungen als "|cffffff00%s|r" gespeichert - dieser Charakter verwendet es jetzt.',
    ['No settings profile named "|cffffff00%s|r".'] = 'Kein Einstellungsprofil namens "|cffffff00%s|r".',
    ['Already using settings profile "|cffffff00%s|r".'] = 'Einstellungsprofil "|cffffff00%s|r" wird bereits verwendet.',
    ['This character now uses settings profile "|cffffff00%s|r".'] = 'Dieser Charakter verwendet jetzt das Einstellungsprofil "|cffffff00%s|r".',
    ["The Default settings profile cannot be deleted."] = "Das Einstellungsprofil Default kann nicht gelöscht werden.",
    ["The Default settings profile cannot be renamed."] = "Das Einstellungsprofil Default kann nicht umbenannt werden.",
    ['Deleted settings profile "|cffffff00%s|r" - this character is back on Default.'] = 'Einstellungsprofil "|cffffff00%s|r" gelöscht - dieser Charakter ist zurück auf Default.',
    ['Deleted settings profile "|cffffff00%s|r".'] = 'Einstellungsprofil "|cffffff00%s|r" gelöscht.',
    ['A settings profile named "|cffffff00%s|r" already exists.'] = 'Ein Einstellungsprofil namens "|cffffff00%s|r" existiert bereits.',
    ['Renamed settings profile "|cffffff00%s|r" to "|cffffff00%s|r".'] = 'Einstellungsprofil "|cffffff00%s|r" in "|cffffff00%s|r" umbenannt.',
    ['Delete settings profile "|cffffff00%s|r"?\n|cffaaaaaaCharacters using it switch to Default. This cannot be undone.|r'] = 'Einstellungsprofil "|cffffff00%s|r" löschen?\n|cffaaaaaaCharaktere, die es verwenden, wechseln zu Default. Das kann nicht rückgängig gemacht werden.|r',
    ["Usage: /ec sprofile save|use|delete|list <name>"] = "Verwendung: /ec sprofile save|use|delete|list <Name>",

