    ["EbonClearance Sell Info"] = "EbonClearance Verkaufsinfo",
    ["Item: %s"] = "Gegenstand: %s",
    ["Kept - 'protect all tomes' is on. Tip: add this item to the Sell List, turn off 'Protect all tomes' in Merchant Settings, or Alt+Right-Click -> Allow Sell to override for this item."] = "Behalten - 'Alle Folianten schützen' ist an. Tipp: Füge diesen Gegenstand zur Verkaufsliste hinzu, deaktiviere 'Alle Folianten schützen' in den Händler-Einstellungen, oder Alt+Rechtsklick -> Verkauf erlauben, um es für diesen Gegenstand zu überschreiben.",
    ["Kept - affix known (Rare/Epic affix protection). Tip: turn off 'Protect Affixed Rare Items' in Keep Settings, or Alt+Right-Click -> Allow Sell to override for this affix."] = "Behalten - Affix bekannt (Schutz für seltene/epische Affixe). Tipp: Deaktiviere 'Affix-behaftete seltene Gegenstände schützen' in den Behalten-Einstellungen, oder Alt+Rechtsklick -> Verkauf erlauben, um es für diesen Affix zu überschreiben.",
    ["Kept - affix needed (Rare/Epic affix you haven't extracted yet). Tip: extract at the Anvil to learn it, or turn off 'Protect Affixed Rare Items', or Alt+Right-Click -> Allow Sell."] = "Behalten - Affix benötigt (seltener/epischer Affix, den du noch nicht extrahiert hast). Tipp: Extrahiere ihn am Amboss, um ihn zu lernen, oder deaktiviere 'Affix-behaftete seltene Gegenstände schützen', oder Alt+Rechtsklick -> Verkauf erlauben.",
    ["Version: %s"] = "Version: %s",
    ["known recipe but bind filter is '%s' and this recipe binds as '%s'. Tip: set this quality's bind filter to '%s' or 'any' in Merchant Settings -> Sell Known Recipes."] = "bekanntes Rezept, aber der Bindungsfilter ist '%s' und dieses Rezept bindet als '%s'. Tipp: Setze den Bindungsfilter dieser Qualität auf '%s' oder 'alle' in Händler-Einstellungen -> Bekannte Rezepte verkaufen.",
    ["known recipe but bind filter is '%s' and this recipe has no bind line (reads as 'any' - only matches filter 'any'). Tip: set this quality's bind filter to 'any' in Merchant Settings -> Sell Known Recipes."] = "bekanntes Rezept, aber der Bindungsfilter ist '%s' und dieses Rezept hat keine Bindungszeile (gilt als 'alle' - passt nur zum Filter 'alle'). Tipp: Setze den Bindungsfilter dieser Qualität auf 'alle' in Händler-Einstellungen -> Bekannte Rezepte verkaufen.",
    ["not detected as a tome/recipe (GetItemInfo class + 'Use: Teaches' tooltip scan both failed)"] = "nicht als Foliant/Rezept erkannt (GetItemInfo-Klasse + 'Use: Teaches'-Tooltip-Scan sind beide fehlgeschlagen)",
    ["rank %d is below your floor of %d, but its item level is above your sell cap for this rarity - kept"] = "Rang %d liegt unter deinem Minimum von %d, aber seine Gegenstandsstufe liegt über deiner Verkaufsobergrenze für diese Seltenheit - behalten",
    ["tome kind is '%s', not 'Recipe' - Sell Known Recipes only applies to profession recipes"] = "Foliant-Art ist '%s', nicht 'Recipe' - Bekannte Rezepte verkaufen gilt nur für Berufsrezepte",
    ["you already have this affix, but its item level is above your sell cap for this rarity - kept"] = "du hast diesen Affix bereits, aber seine Gegenstandsstufe liegt über deiner Verkaufsobergrenze für diese Seltenheit - behalten",
